files.content:
:root {
  --bg: #1a1c2c;
  --card: #2e2f4a;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --border: #f4f4f4;
  --shadow: #0f0f1a;
  --normal: #38b764;
  --under: #41a6f6;
  --over: #ffcd75;
  --obese: #ef7d57;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, var(--shadow) 25%, transparent 25%, transparent 75%, var(--shadow) 75%),
                    linear-gradient(45deg, var(--shadow) 25%, transparent 25%, transparent 75%, var(--shadow) 75%);
  background-size: 8px 8px;
  background-position: 0 0, 4px 4px;
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 28px 24px;
  width: 100%;
  max-width: 380px;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.6rem;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 var(--shadow);
}

.field {
  margin-bottom: 18px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.95rem;
  letter-spacing: 1px;
  text-transform: uppercase;
}

input {
  width: 100%;
  padding: 12px 14px;
  font-family: inherit;
  font-size: 1rem;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input:hover {
  border-color: var(--accent);
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-dark);
}

input::placeholder {
  color: #888;
}

button {
  width: 100%;
  padding: 14px;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  letter-spacing: 2px;
  text-transform: uppercase;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 var(--shadow);
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
  margin-top: 6px;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.result {
  margin-top: 24px;
  padding: 16px;
  border: 3px dashed var(--border);
  min-height: 90px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 8px;
}

.placeholder {
  color: #aaa;
  font-size: 0.9rem;
}

.bmi-value {
  font-size: 2.4rem;
  font-weight: bold;
  line-height: 1;
  text-shadow: 3px 3px 0 var(--shadow);
}

.category {
  font-size: 1.1rem;
  font-weight: bold;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 4px 12px;
  border: 2px solid currentColor;
}

.category.underweight { color: var(--under); }
.category.normal { color: var(--normal); }
.category.overweight { color: var(--over); }
.category.obese { color: var(--obese); }

.error {
  color: var(--obese);
  font-size: 0.95rem;
}

@media (max-width: 400px) {
  body { padding: 12px; }
  .card { padding: 22px 18px; }
  h1 { font-size: 1.3rem; }
  input, button { font-size: 1rem; }
  .bmi-value { font-size: 2rem; }
}

const form = document.getElementById('bmi-form');
const heightInput = document.getElementById('height');
const weightInput = document.getElementById('weight');
const resultDiv = document.getElementById('result');

function getCategory(bmi) {
  if (bmi < 18.5) return { label: 'Underweight', className: 'underweight' };
  if (bmi < 25) return { label: 'Normal', className: 'normal' };
  if (bmi < 30) return { label: 'Overweight', className: 'overweight' };
  return { label: 'Obese', className: 'obese' };
}

function calculateBMI(heightCm, weightKg) {
  const heightM = heightCm / 100;
  return weightKg / (heightM * heightM);
}

function showError(message) {
  resultDiv.innerHTML = `<p class="error">${message}</p>`;
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const height = parseFloat(heightInput.value);
  const weight = parseFloat(weightInput.value);

  if (!height || !weight || height <= 0 || weight <= 0) {
    showError('Please enter valid positive numbers for height and weight.');
    return;
  }

  const bmi = calculateBMI(height, weight);
  const rounded = Math.round(bmi * 10) / 10;
  const category = getCategory(rounded);

  resultDiv.innerHTML = `
    <span class="bmi-value">${rounded.toFixed(1)}</span>
    <span class="category ${category.className}">${category.label}</span>
  `;
});

heightInput.addEventListener('input', () => {
  if (resultDiv.querySelector('.error')) resultDiv.innerHTML = '<p class="placeholder">Enter your height and weight, then press Calculate.</p>';
});
weightInput.addEventListener('input', () => {
  if (resultDiv.querySelector('.error')) resultDiv.innerHTML = '<p class="placeholder">Enter your height and weight, then press Calculate.</p>';
});
